@router.post("/resolve", response_model=MenuItemListResponse)
def resolve_query(query: QueryCreate, db: Session = Depends(get_db)):
    query_obj = queries_repo.create(db, obj_in=query)

    # embed the query and find the closest menu items
    menu_item_ids, context = resolve_query_gemini_top_k(
        db, user_id=query.user_id, query_text=query.query_text
    )
    menu_items = [menu_item_repo.get(db, id=mid) for mid in menu_item_ids]

    for mid in menu_item_ids:
        recommendation_repo.create(db, obj_in=RecommendationCreate(
            query_id=query_obj.id,
            menu_item_id=mid,
            confidence_score=context['confidences'].get(mid, 1.0),
            meta={},
        ))
    return MenuItemListResponse(data=menu_items)

