async def fetch_price(ticker: str) -> Dict[str, Any]:
    """Fetch the current price data for a stock ticker."""
    if not ticker:
        return {"error": "No ticker provided"}

    response = await ticker_price_agent_impl.execute({"ticker": ticker})
    if response.success and response.data:
        return response.data
    return {
        "ticker": ticker,
        "error": response.error_message or f"Failed to fetch price data for {ticker}",
    }

fetch_price_tool = FunctionTool(fetch_price)

ticker_price_agent = Agent(
    name="TickerPriceAgent",
    tools=[fetch_price_tool],
    description="Fetches the current price and related data for a stock",
)

// src/Components/Credits.jsx
export const Credits = ({ entity }) => {
  const firebase = useFirebase();
  const [totalCreds, setTotalCreds] = useState(0);

  const getCredits = async (userId) => {
    const totalCredits = await firebase.getLiveData(
      `${entity}/${userId}/totalCredits`
    );
    // the balance updates live whenever it changes
    onValue(totalCredits, (snapshot) => {
      if (snapshot.exists()) setTotalCreds(snapshot.val());
    });
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(firebaseAuth, (user) => {
      if (user) getCredits(user.uid);
    });
    return () => unsubscribe();
  }, []);
  // ...renders "Your Credits" and {totalCreds}
};
